"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["33587"],{82560(e){e.exports=JSON.parse('{"id":"FIN-1039","slug":"year-end-close","term":"Year-End Close","also_known_as":[],"difficulty":"Advanced","definition":"Year-end close is the process of finalising a company\'s accounts at the end of its financial year, including all month-end tasks plus additional adjustments, checks and preparation for the annual financial statements and audit.","explanation":["Year-end close is the most demanding close of the year. Besides normal month-end tasks, it involves extra work that is often done only annually.","This can include physical stock counts, reviewing assets for impairment, updating provisions and estimates, calculating the annual tax provision, finalising bonuses and accruals, confirming balances with banks and customers, preparing the full financial statements with notes, and providing information to external auditors.","For example, a retailer closing its financial year on 31 January might count all inventory in its stores and warehouses, compare the counts with its records, and write off any missing or damaged stock before finalising its accounts.","Once the year is closed and audited, the accounts are usually locked so that no further changes can be made to that year, and income and expense balances are transferred into retained earnings. Planning the year-end close well in advance helps companies meet deadlines for filing and publishing their annual reports."],"note":"","total":1500,"prev":{"slug":"xirr","term":"XIRR"},"next":{"slug":"year-over-year-growth","term":"Year-over-Year Growth"}}')}}]);